```cpp
/**
 * @file ModbusRTU.h
 * @brief Industrial Modbus RTU Communication Interface for ESP32
 * 
 * @note Uses no STL components, designed for industrial reliability
 * @note Uses Arduino API for hardware abstraction
 * 
 * @defgroup modbus_api Modbus API
 * @defgroup driver_components Driver Internals
 * @defgroup diagnostics Diagnostics & Monitoring
 * @defgroup callbacks Callback Functions
 * @defgroup utility_utils Utility Functions
 * @{
 */

#ifndef MODBUS_RTU_H
#define MODBUS_RTU_H

#include <Arduino.h>
#include <ModbusClientRTU.h>
#include <HardwareSerial.h>
#include <ArduinoLog.h>
#include "ModbusTypes.h"

// --- Feature Flags ---
// #define ENABLE_ADAPTIVE_TIMEOUT      ///< Enables dynamic interval adjustment
// #define DEBUG_INTERVAL_CONTROL       ///< Enables manual interval control

/**
 * @enum E_InitState
 * @brief Initialization state tracking for safety-critical startup monitoring
 * @{
 */
enum E_InitState {
  INIT_NOT_STARTED,     ///< Initialization not begun
  INIT_SERIAL_STARTED,  ///< Serial interface initialized
  INIT_CLIENT_STARTED,  ///< Modbus client started
  INIT_READY,           ///< Fully operational
  INIT_FAILED           ///< Failed during init
};
/** @} */

/**
 * @class ModbusRTU
 * @brief Industrial Modbus RTU communication handler with error resilience
 * 
 * Provides a robust interface for Modbus RTU communication with:
 * - Operation queue management
 * - Adaptive timing control
 * - State monitoring with detailed diagnostics
 * - Callback architecture for custom logic
 */
class ModbusRTU {
public:
    // Construction/Destruction
    /**
     * @brief Construct with default parameters and callback handlers
     * 
     * @param redePin DE/RE pin for RS485 (optional)
     * @param queueSize Maximum pending operations
     * @param baseMinInterval Basic operation interval
     * @param onRegisterChange State change callback
     * @param onWrite Write operation callback
     * @param onError Error handler
     */
    ModbusRTU(int8_t redePin = -1, uint16_t queueSize = 32,
              unsigned long baseMinIntervalMs = 10,
              OnRegisterChangeCallback onRegisterChange = emptyRegisterChangeCallback,
              OnWriteCallback onWrite = emptyWriteCallback,
              OnErrorCallback onError = emptyErrorCallback);

    /// @brief Destructor
    ~ModbusRTU();

    // Initialization & Lifecycle
    /**
     * @brief Start driver instance
     * @param serial Serial interface to use
     * @param baudrate Communication speed (typically 9600)
     */
    MB_Error begin(HardwareSerial &serial, uint32_t baudrate = 9600);

    /// @brief Stop driver and release resources
    void end();

    /// @brief Check operational readiness
    bool isReady() const { return ready && initState == INIT_READY; }

    // Main operational loop
    /// @brief Process pending operations and state machine 
    MB_Error process();

    // Error recovery
    /// @brief Initiate recovery sequence
    MB_Error reset(bool fullReset = false);

    // Discrete Value (Coil) Operations
    /// @defgroup coil_ops Coil Operations
    /// @{
    MB_Error readCoil(uint8_t slaveId, uint16_t address);
    MB_Error writeCoil(uint8_t slaveId, uint16_t address, bool value);
    bool getCoilValue(uint8_t slaveId, uint16_t address, bool &value) const;
    bool isCoilSynchronized(uint8_t slaveId, uint16_t address) const;
    /// @}

    // Register Operations
    /// @defgroup reg_ops Register Operations
    /// @{
    MB_Error readRegister(uint8_t slaveId, uint16_t address);
    MB_Error writeRegister(uint8_t slaveId, uint16_t address, uint16_t value, bool force = false);
    MB_Error writeMultipleRegisters(uint8_t slaveId, uint16_t startAddress, uint16_t quantity, uint16_t value);
    bool getRegisterValue(uint8_t slaveId, uint16_t address, uint16_t &value) const;
    bool isRegisterSynchronized(uint8_t slaveId, uint16_t address) const;
    /// @}

    // Bulk Operations
    /// @defgroup bulk_ops Bulk Access
    /// @{
    MB_Error readHoldingRegisters(uint8_t slaveId, uint16_t address, uint16_t quantity);
    MB_Error readInputRegisters(uint8_t slaveId, uint16_t address, uint16_t quantity);
    MB_Error readCoils(uint8_t slaveId, uint16_t address, uint16_t quantity);
    MB_Error readDiscreteInputs(uint8_t slaveId, uint16_t address, uint16_t quantity);
    /// @}

    // Diagnostics
    /// @defgroup diag_stats Statistics
    /// @{
    bool hasErrors() const { return errorCount > 0; }
    uint32_t getErrorCount() const { return errorCount; }
    uint32_t getSuccessCount() const { return successCount; }
    float getSuccessRate() const;
    void clearStats();
    /// @}

    /// @defgroup debug_diag Debug Tools
    /// @{
    void printStatus() const;
    void printSlaveData(uint8_t slaveId = 0) const;
    void printQueue() const;
    /// @}

    // Operation Management
    /**
     * @brief Check for pending operations
     * @param slaveId 0 for any, specific ID for filter
     * @return true if operations pending
     */
    bool hasPendingOperations(uint8_t slaveId = 0) const;

    /**
     * @brief Query operations by criteria
     * @param results Output array for matching ops
     * @param maxResults Array capacity
     * @param slaveId 0 for any
     * @param flags Status and type filters
     * @param status Op status match
     * @param type Fn code match
     * @return Number of matches found
     */
    uint8_t getOperations(ModbusOperation *results[], uint8_t maxResults, 
                         uint8_t slaveId = 0, uint8_t flags = 0,
                         E_MB_OpStatus *status = nullptr, 
                         E_FN_CODE *type = nullptr) const;

    // Callback Configuration
    /**
     * @defgroup user_callbacks User Callbacks
     * @{
     */
    void setResponseCallback(ResponseCallback callback);
    void setOnRegisterChangeCallback(OnRegisterChangeCallback callback);
    void setOnWriteCallback(OnWriteCallback callback);
    void setOnErrorCallback(OnErrorCallback callback);
    /// @}

    // Filter Management
    /**
     * @defgroup filters Operation Filters
     * @{
     */
    void addFilter(ModbusOperationFilter *filter);
    void clearFilters();
    bool isOperationAlreadyPending(const ModbusOperation &op) const;
    /// @}

    // Timing Control
#ifdef ENABLE_ADAPTIVE_TIMEOUT
    /** 
     * @defgroup adaptive_interval Adaptive Timing
     * @{
     */
    void setAdaptiveInterval(unsigned long baseInterval = 50,
                            unsigned long maxInterval = 1000,
                            unsigned long increaseStep = 50,
                            uint16_t decreaseThreshold = 10,
                            unsigned long decreaseStep = 10);
    /** @} */

    /// @brief Get current operation interval
    unsigned long getCurrentMinInterval() const { return minOperationInterval; }
#else
    /// @brief Get fixed operation interval
    unsigned long getCurrentMinInterval() const { return minOperationInterval; }
#endif

#ifdef DEBUG_INTERVAL_CONTROL
    /// @brief [DEBUG] Force interval change (for testing)
    void _forceSetMinInterval(unsigned long newInterval);
#endif

    // Resource Management & Internals
    void clearQueue();

    /**
     * @defgroup internal_data Data Access
     * @{
     */
    const ModbusOperation* getOperationQueue() const;
    uint8_t getOperationCount() const;
    const SlaveData* getSlaveData() const;
    uint8_t getMaxSlaves() const;
    /// @}

private:
    // Core Components
    ModbusClientRTU *client;
    bool ready;
    int8_t rePin;
    uint16_t maxQueueSize;
    HardwareSerial *serial;
    uint32_t baudRate;

    // Callbacks
    OnRegisterChangeCallback onRegisterChangeCallback;
    OnWriteCallback onWriteCallback;
    OnErrorCallback onErrorCallback;
    ResponseCallback responseCallback;

    // State Management
    SlaveData slaveData[MAX_MODBUS_SLAVES];                 ///< 1-based indexing
    ModbusOperation operationQueue[MAX_PENDING_OPERATIONS];  ///< Operation FIFO
    uint8_t operationCount;                                 ///< Active count

    // Initialization State
